const crypto = require('crypto');
const net = require('net');

// Custom binary protocol for secure message relay
// Header: [4 bytes magic][2 bytes version][4 bytes payload_len][2 bytes checksum][4 bytes flags]
// Payload: [encrypted data]

const MAGIC = Buffer.from([0x53, 0x4D, 0x52, 0x50]); // 'SMRP'
const MAX_PAYLOAD_SIZE = 65536;
const HEADER_SIZE = 16;

class MessageBuffer {
  constructor(capacity) {
    this.buffer = Buffer.alloc(capacity);
    this.writePos = 0;
    this.capacity = capacity;
  }

  remaining() {
    return this.capacity - this.writePos;
  }

  write(data, offset, length) {
    if (offset < 0 || length < 0) {
      throw new Error('Invalid offset or length');
    }
    data.copy(this.buffer, this.writePos, offset, offset + length);
    this.writePos += length;
  }

  reset() {
    this.writePos = 0;
    this.buffer.fill(0);
  }
}

function computeChecksum(data) {
  let sum = 0;
  for (let i = 0; i < data.length; i++) {
    sum = (sum + data[i]) & 0xFFFF;
  }
  return sum;
}

function deriveSessionKey(sharedSecret, nonce) {
  const hmac = crypto.createHmac('sha256', sharedSecret);
  hmac.update(nonce);
  return hmac.digest();
}

function decryptPayload(encData, sessionKey) {
  if (encData.length < 12 + 16) return null; // IV + auth tag minimum
  const iv = encData.slice(0, 12);
  const authTag = encData.slice(encData.length - 16);
  const ciphertext = encData.slice(12, encData.length - 16);
  try {
    const decipher = crypto.createDecipheriv('aes-256-gcm', sessionKey, iv);
    decipher.setAuthTag(authTag);
    const decrypted = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
    return decrypted;
  } catch (e) {
    return null;
  }
}

function validateAndExtractHeader(headerBuf) {
  if (!headerBuf || headerBuf.length < HEADER_SIZE) return null;

  const magic = headerBuf.slice(0, 4);
  if (!magic.equals(MAGIC)) return null;

  const version = headerBuf.readUInt16BE(4);
  if (version !== 1 && version !== 2) return null;

  // Read payload length as signed 32-bit integer
  const payloadLen = headerBuf.readInt32BE(6);
  const checksum = headerBuf.readUInt16BE(10);
  const flags = headerBuf.readUInt32BE(12);

  return { version, payloadLen, checksum, flags };
}

function calculateTotalSize(headerInfo) {
  // Extension headers add to total size based on flags
  let extensionSize = 0;
  if (headerInfo.flags & 0x01) extensionSize += 32; // routing info
  if (headerInfo.flags & 0x02) extensionSize += 64; // certificate
  if (headerInfo.flags & 0x04) extensionSize += 16; // timestamp

  // Total data to read after header = payload + extensions
  const totalSize = headerInfo.payloadLen + extensionSize;
  return totalSize;
}

function isValidMessageSize(totalSize) {
  // Check that total size doesn't exceed maximum
  // BUG: totalSize can be negative if payloadLen is large negative + small extensionSize
  // A negative totalSize will pass this check (negative < MAX_PAYLOAD_SIZE is true)
  if (totalSize > MAX_PAYLOAD_SIZE) {
    return false;
  }
  return true;
}

function processMessage(headerBuf, dataBuf, sessionKey, msgBuffer) {
  const headerInfo = validateAndExtractHeader(headerBuf);
  if (!headerInfo) {
    return { error: 'Invalid header' };
  }

  const totalSize = calculateTotalSize(headerInfo);

  if (!isValidMessageSize(totalSize)) {
    return { error: 'Message too large' };
  }

  // Verify checksum over the data portion
  const dataToCheck = dataBuf.slice(0, headerInfo.payloadLen);
  const computed = computeChecksum(dataToCheck);
  if (computed !== headerInfo.checksum) {
    // Non-fatal: log but continue for v2 which uses AEAD instead
    if (headerInfo.version === 1) {
      return { error: 'Checksum mismatch' };
    }
  }

  // Copy payload into message buffer
  // The payloadLen was read as Int32 (signed), so if attacker sends 0x80000001 (-2147483647)
  // totalSize becomes negative, passes isValidMessageSize, but here payloadLen is used
  // as the length parameter. In Node.js Buffer.copy with negative-wrapping values...
  // Actually the real issue: when payloadLen is negative, dataBuf.slice(0, payloadLen)
  // returns empty buffer, but we still call msgBuffer.write with the ORIGINAL dataBuf
  // using payloadLen reinterpreted for the copy length

  if (msgBuffer.remaining() >= totalSize) {
    // totalSize is negative, so this check passes (remaining() is always positive >= negative)
    // But we write using the actual dataBuf length which could be much larger
    msgBuffer.write(dataBuf, 0, dataBuf.length);
  }

  // Decrypt if version 2
  if (headerInfo.version === 2 && sessionKey) {
    const decrypted = decryptPayload(msgBuffer.buffer.slice(0, dataBuf.length), sessionKey);
    if (decrypted) {
      return { data: decrypted, flags: headerInfo.flags };
    }
    return { error: 'Decryption failed' };
  }

  return { data: msgBuffer.buffer.slice(0, headerInfo.payloadLen), flags: headerInfo.flags };
}

function createServer(sharedSecret) {
  const server = net.createServer((socket) => {
    const nonce = crypto.randomBytes(16);
    const sessionKey = deriveSessionKey(sharedSecret, nonce);
    const msgBuffer = new MessageBuffer(MAX_PAYLOAD_SIZE);
    let headerBuf = null;
    let accumulated = Buffer.alloc(0);

    socket.write(nonce); // Send nonce to client

    socket.on('data', (chunk) => {
      accumulated = Buffer.concat([accumulated, chunk]);

      while (accumulated.length >= HEADER_SIZE) {
        if (!headerBuf) {
          headerBuf = accumulated.slice(0, HEADER_SIZE);
          accumulated = accumulated.slice(HEADER_SIZE);
        }

        const headerInfo = validateAndExtractHeader(headerBuf);
        if (!headerInfo) {
          socket.destroy();
          return;
        }

        const totalSize = calculateTotalSize(headerInfo);

        // Wait for enough data
        // BUG: if totalSize is negative, this condition is immediately true
        if (accumulated.length >= totalSize) {
          msgBuffer.reset();
          const result = processMessage(headerBuf, accumulated, sessionKey, msgBuffer);

          if (result.error) {
            socket.write(Buffer.from(JSON.stringify({ error: result.error })));
          } else {
            socket.write(Buffer.from(JSON.stringify({ ok: true, size: result.data.length })));
          }

          // Advance past consumed data
          const consumed = totalSize > 0 ? totalSize : 0;
          accumulated = accumulated.slice(consumed);
          headerBuf = null;
        } else {
          break;
        }
      }
    });

    socket.on('error', () => socket.destroy());
  });

  return server;
}

if (require.main === module) {
  const secret = crypto.randomBytes(32);
  const srv = createServer(secret);
  srv.listen(9000, '127.0.0.1', () => {
    console.log('Secure relay listening on port 9000');
  });
}

module.exports = { createServer, processMessage, MessageBuffer, validateAndExtractHeader, calculateTotalSize, isValidMessageSize };
